package com.propbuy.security;
import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.web.cors.*; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f,@Value("${app.cors-origins}") String origins) throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOriginPatterns(Arrays.stream(origins.split(",")).map(String::trim).filter(s->!s.isBlank()).toList());x.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS","PATCH"));x.setAllowedHeaders(List.of("Authorization","Content-Type","X-Requested-With","Accept","Origin"));x.setAllowCredentials(true);return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/health","/api/properties/published/*","/api/properties/*/images/*","/","/index.html","/assets/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).build();} }
